document.addEventListener('input',ev=>{if(ev.target.closest('#publish-form')){setDraftFromForm();if(ev.target.id==='pub-negotiable'){const p=$('#pub-price');if(p)p.disabled=ev.target.checked;}}});
async function compressAvatar(file) {
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Выберите JPEG, PNG или WebP');
 if(file.size>12*1024*1024)throw Error('Фото слишком большое (максимум 12 МБ)');
 const objectUrl=URL.createObjectURL(file);
 try {
   const picture=new Image();
   await new Promise((resolve,reject)=>{picture.onload=resolve;picture.onerror=()=>reject(new Error('Не удалось открыть изображение'));picture.src=objectUrl});
   const scale=Math.min(1,512/Math.max(picture.naturalWidth,picture.naturalHeight));
   const canvas=document.createElement('canvas');
   canvas.width=Math.max(1,Math.round(picture.naturalWidth*scale));
   canvas.height=Math.max(1,Math.round(picture.naturalHeight*scale));
   const context=canvas.getContext('2d');
   if(!context)throw Error('Обработка фото недоступна');
   context.drawImage(picture,0,0,canvas.width,canvas.height);
   for(const quality of [0.83,0.70,0.55,0.4]) {
     const result=canvas.toDataURL('image/jpeg',quality);
     if(result.length<400000)return result;
   }
   throw Error('Фото слишком большое, выберите другое');
 } finally {URL.revokeObjectURL(objectUrl)}
}
document.addEventListener('change',async ev=>{const input=ev.target;if(input.id!=='profile-photo'&&input.id!=='pub-photo')return;const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Выберите изображение');input.value='';return;}if(file.size>1024*1024){toast('Фото больше 1 МБ. Выберите файл меньшего размера.');input.value='';return;}if(input.id==='profile-photo'&&me()){
   try {
     const photo=await compressAvatar(file);
     if(remoteMode) await mutateRemote('/profile',{name:me().name,car:me().car||'',phone:me().phone||'',photo},'Фото профиля сохранено');
     else {me().photo=photo;save();render();toast('Фото профиля обновлено');}
   } catch(err){toast(err.message||'Не удалось обработать фото')} finally {input.value=''}
 } else {
   const reader=new FileReader();
   reader.onload=()=>{const d=publishDraft();d.photo=reader.result;db.draft=d;save();toast('Фото автомобиля добавлено к черновику')};
   reader.readAsDataURL(file);
 }});
